contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public {
        require(caller != address(this), "caller must be an external account, not this test contract");

        // caller is the test contract, so onlyOwner calls should revert.
        // Observe initial owner-controlled state through public getters.
        uint32 pIdBefore = c.cvxPoolInfo().pId;
        address tokenBefore = c.cvxPoolInfo().token;
        address rewardsBefore = c.cvxPoolInfo().rewards;
        address operatorBefore = c.operator();
        address rewardsRecipientBefore = c.rewardsRecipient();

        bool revertedSetCvxPoolInfo;
        try c.setCvxPoolInfo(7, address(0xdead), address(0xbeef)) {
            revertedSetCvxPoolInfo = false;
        } catch {
            revertedSetCvxPoolInfo = true;
        }

        bool revertedSetOperator;
        try c.setOperator(address(0xdead)) {
            revertedSetOperator = false;
        } catch {
            revertedSetOperator = true;
        }

        bool revertedSetRewardsRecipient;
        try c.setRewardsRecipient(address(0xbeef)) {
            revertedSetRewardsRecipient = false;
        } catch {
            revertedSetRewardsRecipient = true;
        }

        assert(
            revertedSetCvxPoolInfo &&
            revertedSetOperator &&
            revertedSetRewardsRecipient &&
            c.cvxPoolInfo().pId == pIdBefore &&
            c.cvxPoolInfo().token == tokenBefore &&
            c.cvxPoolInfo().rewards == rewardsBefore &&
            c.operator() == operatorBefore &&
            c.rewardsRecipient() == rewardsRecipientBefore
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address recipient) public {
        // The test contract itself is the owner of c. Choose a caller that is not the owner.
        require(newOwner != address(this));
        require(newOwner != address(0));

        // Read owner-controlled state through public getters before the privileged calls.
        (address cvxTokenBefore, address cvxRewardsBefore, uint32 cvxPidBefore) = c.cvxPoolInfo();
        address operatorBefore = c.operator();
        address rewardsRecipientBefore = c.rewardsRecipient();
        address ownerBefore = c.owner();

        // Privileged owner-only calls by a non-owner via the test contract.
        // transferOwnership, setCvxPoolInfo etc. must revert.
        bool revertedTransferOwnership;
        try c.transferOwnership(newOwner) {
            revertedTransferOwnership = false;
        } catch {
            revertedTransferOwnership = true;
        }

        bool revertedSetCvxPoolInfo;
        try c.setCvxPoolInfo(7, address(0xdead), address(0xbeef)) {
            revertedSetCvxPoolInfo = false;
        } catch {
            revertedSetCvxPoolInfo = true;
        }

        bool revertedSetOperator;
        try c.setOperator(recipient) {
            revertedSetOperator = false;
        } catch {
            revertedSetOperator = true;
        }

        bool revertedSetRewardsRecipient;
        try c.setRewardsRecipient(recipient) {
            revertedSetRewardsRecipient = false;
        } catch {
            revertedSetRewardsRecipient = true;
        }

        // recoverToken is also onlyOwner; call it with the test contract's own token balance, if any,
        // but since the owner is this test contract, a non-owner caller cannot invoke it.
        bool revertedRecoverToken;
        try c.recoverToken(address(0xdead), recipient, 0) {
            revertedRecoverToken = false;
        } catch {
            revertedRecoverToken = true;
        }

        // After the reverting calls, owner-controlled state must be unchanged.
        (address cvxTokenAfter, address cvxRewardsAfter, uint32 cvxPidAfter) = c.cvxPoolInfo();
        address operatorAfter = c.operator();
        address rewardsRecipientAfter = c.rewardsRecipient();
        address ownerAfter = c.owner();

        assert(
            revertedTransferOwnership &&
            revertedSetCvxPoolInfo &&
            revertedSetOperator &&
            revertedSetRewardsRecipient &&
            revertedRecoverToken &&
            cvxTokenAfter == cvxTokenBefore &&
            cvxRewardsAfter == cvxRewardsBefore &&
            cvxPidAfter == cvxPidBefore &&
            operatorAfter == operatorBefore &&
            rewardsRecipientAfter == rewardsRecipientBefore &&
            ownerAfter == ownerBefore
        );
    }
}

