contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        bool stakedReverted;
        bool earnedReverted;
        bool shutdownReverted;
        uint256 stakedBefore;
        uint256 earnedBefore;
        bool shutdownBefore;
        uint256 stakedAfter;
        uint256 earnedAfter;
        bool shutdownAfter;

        stakedBefore = c.stakedBalance();
        earnedBefore = c.earned();
        shutdownBefore = c.isCvxShutdown();

        try c.stakedBalance() returns (uint256 v) {
            stakedAfter = v;
            stakedReverted = false;
        } catch {
            stakedAfter = 0;
            stakedReverted = true;
        }

        try c.earned() returns (uint256 v) {
            earnedAfter = v;
            earnedReverted = false;
        } catch {
            earnedAfter = 0;
            earnedReverted = true;
        }

        try c.isCvxShutdown() returns (bool v) {
            shutdownAfter = v;
            shutdownReverted = false;
        } catch {
            shutdownAfter = false;
            shutdownReverted = true;
        }

        assert(
            !stakedReverted &&
            !earnedReverted &&
            !shutdownReverted &&
            stakedAfter == stakedBefore &&
            earnedAfter == earnedBefore &&
            shutdownAfter == shutdownBefore
        );
    }
}

