contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOperator, address newRewardsRecipient, bool tryAsNonOwner) public {
        address originalOperator = c.operator();
        address originalRewardsRecipient = c.rewardsRecipient();

        bool ownerSucceeded;
        bool nonOwnerSucceeded;

        if (tryAsNonOwner) {
            // The test contract is not the owner after deployment (constructor belongs to C's deployer logic);
            // try a non-owner call only when it will actually be from a non-owner context.
        } else {
            c.setOperator(newOperator);
            ownerSucceeded = true;
        }

        // Perform a second setOperator call to observe the general update rule.
        c.setOperator(newOperator);
        address observedOperator = c.operator();

        c.setRewardsRecipient(newRewardsRecipient);
        address observedRewardsRecipient = c.rewardsRecipient();

        assert(observedOperator == newOperator && observedRewardsRecipient == newRewardsRecipient);
    }

    receive() external payable {}
}

