contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool claimExtras, address newRecipient, uint256 recipientBeforeBalance, uint256 token0BeforeBalance) public {
        // Precondition: rewardsRecipient is the zero address, so getReward must not forward reward tokens.
        require(c.rewardsRecipient() == address(0), "precondition: rewardsRecipient must be zero");

        // Configure the pool rewards address so that getReward has a target.
        c.setCvxPoolInfo(0, address(0xdead), address(1));

        address token0 = c.rewardTokens(0);

        // Read before values through C's public surface.
        uint256 cBefore = IERC20(token0).balanceOf(address(c));

        // The deciding call: getReward must not revert and must not move tokens.
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cAfter = IERC20(token0).balanceOf(address(c));

        // General rule: if getReward did not revert, the zero-address recipient guard
        // means reward tokens stay in C and no token was forwarded.
        assert(reverted || cAfter == cBefore);
    }

    receive() external payable {}
}

