contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool stakeFlag) public payable {
        require(address(this).balance >= 0);

        // Make sure CVX pool info is set for a benign pool id so depositAndStake can proceed.
        c.setCvxPoolInfo(0, address(c), address(c));

        // Observe state before the deciding call.
        uint256 stakedBefore = c.stakedBalance();

        // Depending on CVX shutdown status for pool 0 in this fresh deployment,
        // either a deposit is made or it is skipped by the contract's own guard.
        bool shutdown = c.isCvxShutdown();

        // This is the deciding operator-gated call. It must not revert when the
        // operator is the caller (which it is, since the test contract deployed c
        // and never changed the operator).
        c.depositAndStake(amount);

        // GENERAL RULE:
        // If the CVX pool was already shutdown, calling depositAndStake(amount)
        // must leave the account's staked CVX reward-pool balance unchanged,
        // because the contract deliberately skips the booster.deposit in that case.
        if (shutdown) {
            assert(c.stakedBalance() == stakedBefore);
        } else {
            // Otherwise the operator's deposit went through (or the booster's
            // own state was updated), so the staked CVX reward balance must be
            // at least the amount the operator deposited.
            assert(c.stakedBalance() >= amount || amount == 0);
        }

        // Additional invariant tying earned() and stakedBalance() together as
        // the public position view: showPositions must report exactly those two.
        C.Position memory pos = c.showPositions();
        assert(pos.staked == c.stakedBalance() && pos.earned == c.earned());

        // Silence unused-variable warning for stakeFlag; it is intentionally not
        // used to vary the rule because depositAndStake hard-codes staking.
        stakeFlag;
    }

    receive() external payable {}
}

