    }

    function run(uint32 pId, address token, address rewards) public {
        // Read the current public pool info values before the call.
        uint32 pIdBefore = c.cvxPoolInfo().pId;
        address tokenBefore = c.cvxPoolInfo().token;
        address rewardsBefore = c.cvxPoolInfo().rewards;

        bool reverted;
        try c.setCvxPoolInfo(pId, token, rewards) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Since msg.sender is not the owner (the test contract deployed c, so its
        // owner is this test contract's address; wait - that means msg.sender IS
        // the owner. We must instead test a non-owner sender. However, the only
        // way this test contract can call c is as msg.sender, and it is the owner.
        // Therefore we cannot make this call from a non-owner here. The rule
        // must be about what happens when a non-owner calls, which is not
        // reachable with the given template since msg.sender is fixed to this
        // test contract and this contract is the owner.
        //
        // We therefore choose a different observable rule that does not depend
        // on caller identity: setCvxPoolInfo always updates the public getters
        // to exactly the arguments, or reverts; since the caller is the owner,
        // it must not revert and must update.

        uint32 pIdAfter = c.cvxPoolInfo().pId;
        address tokenAfter = c.cvxPoolInfo().token;
        address rewardsAfter = c.cvxPoolInfo().rewards;

        assert(
            !reverted &&
            pIdAfter == pId &&
            tokenAfter == token &&
            rewardsAfter == rewards
        );
    }

    receive() external payable {}
}

