contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint32 newPId,
        address newToken,
        address newRewards,
        address newOperator,
        address newRecipient
    ) public {
        // Read owner-restricted configuration before the unauthorized calls.
        uint32 oldPId = c.cvxPoolInfo().pId;
        address oldToken = c.cvxPoolInfo().token;
        address oldRewards = c.cvxPoolInfo().rewards;
        address oldOperator = c.operator();
        address oldRecipient = c.rewardsRecipient();

        // The test contract is the owner of c; direct calls would succeed.
        // Use an external helper contract to attempt these calls as a non-owner.
        DirectCaller dc;
        // If the current owner is not this contract, this deployment may revert;
        // the test's only guarantee is for the owner case, so we require it.
        require(c.owner() == address(this), "test must own c");
        dc = new DirectCaller();

        bool revertedSetPool = dc.attemptSetCvxPoolInfo(
            address(c),
            newPId,
            newToken,
            newRewards
        );
        bool revertedSetOperator = dc.attemptSetOperator(address(c), newOperator);
        bool revertedSetRecipient = dc.attemptSetRewardsRecipient(address(c), newRecipient);

        // Read configuration after the unauthorized attempts.
        CvxPoolInfo memory afterCvx = c.cvxPoolInfo();
        address afterOperator = c.operator();
        address afterRecipient = c.rewardsRecipient();

        assert(
            revertedSetPool &&
                revertedSetOperator &&
                revertedSetRecipient &&
                afterCvx.pId == oldPId &&
                afterCvx.token == oldToken &&
                afterCvx.rewards == oldRewards &&
                afterOperator == oldOperator &&
                afterRecipient == oldRecipient
        );
    }
}

contract DirectCaller {
    function attemptSetCvxPoolInfo(
        address target,
        uint32 _pId,
        address _token,
        address _rewards
    ) external returns (bool reverted) {
        C c = C(target);
        try c.setCvxPoolInfo(_pId, _token, _rewards) {
            reverted = false;
        } catch {
            reverted = true;
        }
    }

    function attemptSetOperator(address target, address _operator) external returns (bool reverted) {
        C c = C(target);
        try c.setOperator(_operator) {
            reverted = false;
        } catch {
            reverted = true;
        }
    }

    function attemptSetRewardsRecipient(address target, address _recipient) external returns (bool reverted) {
        C c = C(target);
        try c.setRewardsRecipient(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
    }
}

