contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOperator, uint256 amount) public {
        require(amount > 0, "amount must be positive");

        // Setup: the test contract owns c.
        // Change the operator to newOperator — a successful state change.
        c.setOperator(newOperator);

        // Precondition required for correctness of the property:
        // make sure the call we are about to try does not revert for a reason
        // OTHER than the operator check. In particular the CVX pool must not be
        // shut down.  If it were shut down `depositAndStake` would be a no-op and
        // our rule could not be observed.  Requiring the pool to be live is a
        // GENERAL precondition (for a live pool the rule must hold for all inputs).
        require(!c.isCvxShutdown(), "pool is shut down");

        // The deciding call: depositAndStake is onlyOperator.  The freshly
        // installed operator is newOperator, which is *not* msg.sender (the test
        // contract), so this call from the test contract must revert.  A faulty
        // version that forgot to enforce the operator would not revert here.
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // GENERAL RULE: after setOperator(newOperator), a depositAndStake call
        // from any address other than newOperator reverts.  In this harness the
        // caller is always this test contract (which is not newOperator),
        // therefore the call must revert.
        assert(reverted);
    }
}

