contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public {
        // Only exercise the owner path so the wrapper is authorized.
        require(msg.sender == c.owner(), "caller is not owner");

        // Ensure the wrapper actually holds enough tokens for the direct-transfer path.
        // This makes the deciding call non-reverting and lets us assert an exact numeric result.
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));
        require(beforeBalance >= amount, "wrapper balance too small");

        // Precondition for exact accounting: the pool has no unaccounted staked balance.
        require(c.stakedBalance() == 0, "staked balance must be zero");

        // Perform the state-changing call as a top-level statement.
        c.withdrawAndUnwrap(amount, claim, to);

        // General rule: since clpBalance >= amount, toUnstake = 0,
        // no value is unstaked. Tokens are transferred only when to != 0,
        // and in that case exactly `amount` tokens leave the wrapper.
        uint256 afterBalance = c.clpToken().balanceOf(address(c));
        if (to != address(0)) {
            assert(afterBalance == beforeBalance - amount);
        } else {
            assert(afterBalance == beforeBalance);
        }
    }
}

