contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);

        // Read pre-state through c's public surface only.
        uint32 pId = c.cvxPoolInfo().pId;
        address poolToken = c.cvxPoolInfo().token;
        address rewardsAddr = c.cvxPoolInfo().rewards;
        IERC20 clp = c.clpToken();
        ICVXBooster booster = c.booster();

        // The pool must not be shutdown for the branch we test.
        require(!c.isCvxShutdown());

        // The operator is the only permitted caller.
        require(c.operator() == address(this));

        // If the pool metadata is in place, depositing uses the real token.
        if (poolToken == address(clp) && poolToken != address(0)) {
            uint256 beforeBal = clp.balanceOf(address(c));
            uint256 beforeAllowance = clp.allowance(address(c), address(booster));

            c.depositAndStake(amount);

            uint256 afterAllowance = clp.allowance(address(c), address(booster));
            uint256 afterBal = clp.balanceOf(address(c));

            // If the pool is real, the deposit cannot grant more than the requested amount,
            // and the allowance can only rise on top of the pre-existing allowance.
            if (poolToken.code.length > 0 && rewardsAddr.code.length > 0) {
                assert(afterAllowance <= beforeAllowance + beforeBal);
            } else {
                // No meaningful pool: the call should not have moved the allowance.
                assert(afterAllowance <= beforeAllowance);
            }
        } else {
            // Without valid pool metadata, the call must not change the allowance for a hard-coded
            // pool token. This distinguishes a correctly guarded deposit from an unguarded one.
            uint256 beforeAllowance = clp.allowance(address(c), address(booster));

            c.depositAndStake(amount);

            uint256 afterAllowance = clp.allowance(address(c), address(booster));
            assert(afterAllowance == beforeAllowance);
        }
    }
}

