    function run(uint256 amount, address to) public {
        require(to != address(0), "recipient must be nonzero");

        uint256 balBefore = c.clpToken().balanceOf(address(c));
        uint256 toBefore = c.clpToken().balanceOf(to);

        bool reverted;
        try c.withdrawAndUnwrap(amount, false, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.clpToken().balanceOf(address(c));
        uint256 toAfter = c.clpToken().balanceOf(to);

        assert(reverted || (toAfter == toBefore + amount && balAfter + amount == balBefore));
    }
}

