        bool reverted;

        if (tryOperator) {
            try c.setOperator(someOperator) {
                reverted = false;
            } catch {
                reverted = true;
            }
            if (msg.sender != c.owner()) {
                assert(reverted && c.operator() != someOperator);
            } else {
                assert(!reverted && c.operator() == someOperator);
            }
        } else {
            try c.setRewardsRecipient(someRecipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            if (msg.sender != c.owner()) {
                assert(reverted && c.rewardsRecipient() != someRecipient);
            } else {
                assert(!reverted && c.rewardsRecipient() == someRecipient);
            }
        }
    }
}

